  end

  on_linux do
    on_arm do
      url "https://github.com/reliaburger/reliaburger/releases/download/v0.2.7/relish-linux-aarch64"
      sha256 "8c663056cfce5f55c6b2741498b570dcc31822a8d35474651a1d67679109a8df"
    end
    on_intel do
      url "https://github.com/reliaburger/reliaburger/releases/download/v0.2.7/relish-linux-x86_64"
      sha256 "e05752120e2ce2aaf78527e27336d48cbd39d84ac52f53deed7aa1226bb738d7"
    end
  end

  def install
    # The release asset is the bare binary, named for its platform.
    bin.install Dir["relish-*"].fetch(0) => "relish"
